    wire [7:0] __bd_mux_0_input0;
    wire [7:0] __bd_mux_0_input1;
    wire __bd_mux_0_select;
    wire [7:0] __bd_mux_0_result;
    wire [7:0] slice_bus;
    wire [7:0] concat_bus;
    wire select_net;
    wire [7:0] result_bus;
    wire [7:0] constant_bus;

    assign slice_bus = data[7:0];
    assign __bd_mux_0_input0 = slice_bus;
    assign concat_bus = {data[15:12], 4'd5};
    assign __bd_mux_0_input1 = concat_bus;
    assign select_net = select;
    assign __bd_mux_0_select = select_net;
    assign result_bus = __bd_mux_0_result;
    assign result = result_bus;
    assign constant_bus = 8'd5;
    assign fixed = constant_bus;

    bd_mux2 #(
        .WIDTH(8)
    ) mux_0 (
        .input0(__bd_mux_0_input0),
        .input1(__bd_mux_0_input1),
        .select(__bd_mux_0_select),
        .result(__bd_mux_0_result)
    );
endmodule

